function validate([road, budget]) {
  if (typeof road !== 'string' || road.length < 1 || road.length > 100000) return 'road has 1 to 100000 characters.';
  if (!/^[.x]+$/.test(road)) return "road uses only '.' and 'x'.";
  if (!Number.isInteger(budget) || budget < 1 || budget > 100001) return 'budget is between 1 and 100001.';
  return null;
}

