function maxPotholes(road, budget) {
  const runs = [];
  let length = 0;
  for (const ch of road) {
    if (ch === 'x') {
      length++;
    } else if (length > 0) {
      runs.push(length);
      length = 0;
    }
  }
  if (length > 0) runs.push(length);
  runs.sort((a, b) => b - a);
  let fixed = 0;
  for (const run of runs) {
    if (budget < 2) break;
    const take = Math.min(run, budget - 1);
    fixed += take;
    budget -= take + 1;
  }
  return fixed;
}

