function maxPotholes(road, budget) {
  // Decide pothole by pothole: skip it, extend the job on the previous pothole (+1), or start a new job (+2).
  const memo = new Map();
  const best = (i, left, open) => {
    if (i === road.length) return 0;
    const key = `${i},${left},${open}`;
    if (memo.has(key)) return memo.get(key);
    let result;
    if (road[i] === '.') result = best(i + 1, left, false);
    else {
      result = best(i + 1, left, false);
      const cost = open ? 1 : 2;
      if (left >= cost) result = Math.max(result, 1 + best(i + 1, left - cost, true));
    }
    memo.set(key, result);
    return result;
  };
  return best(0, budget, false);
}

