function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 12);
    const p = rand();
    let road = '';
    for (let i = 0; i < n; i++) road += rand() < p ? 'x' : '.';
    return [road, pick(1, 20)];
  }
  let road = '';
  let cost = 0;
  while (road.length < 10000) {
    road += '.'.repeat(pick(1, 4));
    const run = rand() < 0.1 ? pick(20, 200) : pick(1, 12);
    road += 'x'.repeat(run);
    cost += run + 1;
  }
  road = road.slice(0, 10000);
  const budget = rand() < 0.2 ? 100001 : pick(1, Math.min(100001, cost));
  return [road, budget];
}
